import { forwardRef, type ImgHTMLAttributes } from "react";
import manifest from "@/data/imageManifest.json";

type Entry = { w: number; h: number; v: number[] };
const images = manifest as Record<string, Entry>;

/** Default: full width on phones, about half the screen on larger layouts. */
const DEFAULT_SIZES = "(min-width: 1280px) 640px, (min-width: 768px) 50vw, 100vw";

const encode = (url: string) => encodeURI(url);

/**
 * Drop-in replacement for <img>. For images listed in imageManifest.json
 * (generated by `pnpm images`) it adds:
 * - srcSet with 480/960/1600px copies, so phones don't download desktop files;
 * - width/height, so the browser reserves space and the layout doesn't jump.
 * Unknown images (e.g. CMS uploads, Cloudinary) render as a plain <img>.
 * Pass `sizes` when an image is much narrower or wider than the default.
 */
export const Img = forwardRef<HTMLImageElement, ImgHTMLAttributes<HTMLImageElement>>(
  function Img({ src, srcSet, sizes, width, height, ...rest }, ref) {
    const entry = typeof src === "string" ? images[src] : undefined;
    if (!entry || srcSet) {
      return <img ref={ref} src={src} srcSet={srcSet} sizes={sizes} width={width} height={height} {...rest} />;
    }
    const base = (src as string).replace(/\.webp$/, "");
    const candidates = [
      ...entry.v.map(w => `${encode(`${base}.w${w}.webp`)} ${w}w`),
      `${encode(src as string)} ${entry.w}w`,
    ];
    return (
      <img
        ref={ref}
        src={src}
        srcSet={candidates.join(", ")}
        sizes={sizes ?? DEFAULT_SIZES}
        width={width ?? entry.w}
        height={height ?? entry.h}
        {...rest}
      />
    );
  }
);
